package kr.workbench;
import static kr.workbench.BountyFeaturesTest.*;import burp.api.montoya.*;import burp.api.montoya.http.message.*;import burp.api.montoya.collaborator.*;import java.util.*;import java.util.List;import java.util.concurrent.atomic.*;import java.time.*;
/** Collaborator control flow uses a deterministic fake service, never an external callback. */
public final class IntegrationEdgesTest extends WorkbenchTest {
 public static void main(String[] args)throws Exception{
  factory();var q=rq("https://auth.test/one","GET","",List.of(header("Cookie","SID=A")));check(!AuthComparePanel.sameTarget(q,q.withMethod("POST")),"changed actual method invalidates provenance");check(!AuthComparePanel.sameTarget(q,rq("https://other.test/one","GET","",List.of())),"changed actual origin invalidates provenance");check(!AuthComparePanel.sameTarget(q,rq("https://auth.test/two","GET","",List.of())),"changed actual path invalidates provenance");
  AtomicInteger issued=new AtomicInteger(),polls=new AtomicInteger();InteractionId id=proxy(InteractionId.class,(p,m,a)->"test-payload-id");var payload=proxy(CollaboratorPayload.class,(p,m,a)->switch(m.getName()){case "id"->id;case "toString"->"test-payload-id.example.invalid";default->def(m);});var interaction=proxy(Interaction.class,(p,m,a)->switch(m.getName()){case "id"->id;case "type"->InteractionType.HTTP;case "timeStamp"->ZonedDateTime.parse("2026-10-11T00:00:00Z");default->def(m);});
  var client=proxy(CollaboratorClient.class,(p,m,a)->switch(m.getName()){case "generatePayload"->{issued.incrementAndGet();yield payload;}case "getAllInteractions"->{polls.incrementAndGet();yield List.of(interaction);}default->def(m);});var collaborator=proxy(Collaborator.class,(p,m,a)->m.getName().equals("createClient")?client:def(m));MontoyaApi api=proxy(MontoyaApi.class,(p,m,a)->m.getName().equals("collaborator")?collaborator:def(m));WorkbenchScope scope=WorkbenchScope.install(api);scope.add("https://auth.test/",true);
  AtomicReference<AuthComparePanel> auth=new AtomicReference<>();AtomicReference<ActivityPanel> act=new AtomicReference<>();AtomicReference<BountySupportPanel> ref=new AtomicReference<>();edt(()->{auth.set(new AuthComparePanel(api,List::of));act.set(new ActivityPanel(api));ref.set(new BountySupportPanel(api,()->List.of(AuthRecordTest.rr(q,rs(200,"{}",List.of()))),auth.get(),act.get()));});var p=ref.get();edt(p::generateOast);idle(p);check(issued.get()==1&&p.payload.getText().equals("test-payload-id.example.invalid"),"fake Collaborator payload linked to selected request without target send");edt(p::pollOast);idle(p);check(polls.get()==1&&p.oastModel.getRowCount()==1,"fake interaction polling associates payload id");edt(p::pollOast);idle(p);check(p.oastModel.getRowCount()==1,"repeated interaction polling deduplicates events");check(p.oastSnapshot().get(0).get("url").equals(q.url()),"OAST export snapshot retains request provenance");
  AtomicReference<PassiveScanPanel> urls=new AtomicReference<>();edt(()->{urls.set(new PassiveScanPanel(api));urls.get().target.setText("auth.test");urls.get().add(q.url(),"Burp History GET");urls.get().add(q.url(),"OpenAPI POST");});check(urls.get().items.get(q.url()).methods.equals(Set.of("GET","POST")),"URL summary preserves GET and POST discovery");check(urls.get().model.getValueAt(0,9).toString().contains("GET, POST"),"method discovery remains visible independently of GET status");
  int before=p.oastModel.getRowCount();edt(()->{p.oastExternal.setText("bad-time\tDNS\tnot-a-time\tGET\thttps://auth.test/one");rejects(p::importOast,"malformed OAST timestamp rejected atomically");});check(p.oastModel.getRowCount()==before,"invalid timestamp inserts no partial rows");
  edt(()->{p.close();act.get().close();auth.get().close();urls.get().close();});WorkbenchScope.release(api);System.out.println("IntegrationEdgesTest: "+checks+" checks passed");
 }
}
